<style>
.bulk-workspace{display:flex;flex-direction:column;gap:22px;min-width:0}.bulk-workspace *{box-sizing:border-box}.bulk-workspace h1{font-size:28px;font-weight:650;letter-spacing:-.035em}.bulk-workspace h2{font-size:15px;font-weight:600}.bulk-workspace p{line-height:1.65}.bulk-muted{font-size:12px;color:var(--theme-muted-text-color)}.bulk-layout{display:grid;grid-template-columns:minmax(0,1.65fr) minmax(300px,1fr);gap:22px;align-items:start}.bulk-stack{display:flex;flex-direction:column;gap:20px;min-width:0}.bulk-card{background:var(--theme-surface-base);border:1px solid var(--theme-card-border-color);border-radius:12px;min-width:0;scroll-margin-top:85px}.bulk-card>header{padding:17px 20px;border-bottom:1px solid var(--theme-border-color);display:flex;align-items:start;justify-content:space-between;gap:12px}.bulk-card header p{margin-top:4px}.bulk-body{padding:20px;display:flex;flex-direction:column;gap:16px;min-width:0}.bulk-body>div,.bulk-body form{min-width:0}.bulk-body select,.bulk-body input{max-width:100%;min-width:0}.bulk-upload{display:flex;flex-direction:column;align-items:start;gap:12px;padding:22px;border:1px dashed var(--theme-border-color);border-radius:9px;background:var(--theme-surface-soft);font-size:13px}.bulk-upload input{width:100%;font-size:12px}.bulk-upload input::file-selector-button{padding:9px 12px;border:1px solid var(--theme-border-color);border-radius:6px;background:var(--theme-surface-base);color:var(--theme-header-text-color);margin-right:10px;cursor:pointer}.bulk-note{padding:12px 14px;border-radius:8px;background:var(--theme-surface-soft);font-size:12px;line-height:1.6}.bulk-error{color:var(--theme-danger-color);font-size:12px;overflow-wrap:anywhere}.bulk-errors{padding:12px 16px;border-left:3px solid var(--theme-danger-color);background:var(--theme-surface-base);font-size:13px}.bulk-errors ul{list-style:disc;padding-left:16px}.bulk-steps{display:flex;gap:10px;flex-wrap:wrap;font-size:12px;color:var(--theme-muted-text-color)}.bulk-steps 