@media(max-width:1100px){.bulk-layout{grid-template-columns:minmax(0,1fr)}}@media(max-width:600px){.bulk-workspace h1{font-size:25px}.bulk-body{padding:15px}.bulk-card>header{padding:15px;flex-wrap:wrap}.bulk-upload{padding:15px}.bulk-steps{gap:6px}.bulk-steps span{padding:6px 8px}.bulk-history-row{flex-direction:column}.bulk-summary{gap:12px}.bulk-layout{gap:16px}}

.bulk-navigation{display:flex;align-self:flex-start;gap:4px;padding:4px;border:1px solid var(--theme-border-color);border-radius:12px;background:var(--theme-surface-base)}.bulk-navigation .app-ui-button{font-size:12px;color:var(--theme-muted-text-color)}.bulk-navigation .app-ui-button[aria-current=page]{color:var(--theme-accent);background:color-mix(in srgb,var(--theme-accent) 8%,var(--theme-surface-base))}.bulk-detail-navigation{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;font-size:12px}.bulk-detail-navigation a{display:flex;gap:8px;align-items:center;color:var(--theme-accent);font-weight:600}.bulk-detail-navigation>span{color:var(--theme-muted-text-color);font-size:11px}
