00;font-variant-numeric:tabular-nums}.bulk-import-record .app-ui-button{font-size:11px}.bulk-import-record .bulk-badge{padding:7px 10px;font-size:10px}.bulk-import-record .bulk-badge[data-state=partial],.bulk-import-record .bulk-badge[data-state=blocked]{background:color-mix(in srgb,#c38b2b 9%,var(--theme-surface-base));color:var(--theme-warning-color,#a76c15)}.bulk-history-footer{padding:16px 24px;border-top:1px solid var(--theme-divider-border-color);display:flex;justify-content:space-between;gap:16px;align-items:center;flex-wrap:wrap}.bulk-history-footer>span{font-size:11px;color:var(--theme-muted-text-color)}.bulk-history-empty{text-align:center;padding:48px 20px}.bulk-history-empty>.bulk-file-icon{margin:0 auto 20px}.bulk-history-empty h3{font-size:20px;font-weight:600}.bulk-history-empty p{font-size:13px;color:var(--theme-muted-text-color);margin:10px 0 22px}.bulk-import-file a:focus-visible,.bulk-detail-navigation a:focus-visible{outline:2px solid var(--theme-accent);outline-offset:3px}
@media(max-width:1200px){.bulk-import-record{grid-template-columns:minmax(180px,1fr) minmax(220px,1fr);gap:18px}.bulk-import-status{grid-column:1}.bulk-import-record>.app-ui-button{justify-self:end}.bulk-history-filters>div:nth-child(2),.bulk-history-filters>div:nth-child(3){width:160px}}
